/**
 * Every project shown on the site: the cards in the Projects section and the
 * detail pages at #/projects/<slug>. Images live in public/projects/<slug>/
 * (generated by scripts/optimize_images.py); each has a "-thumb" version.
 */

export type ProjectCategory = "AUV" | "Software" | "Research" | "Internship";

export type ProjectResult = { value: string; label: string; note?: string };
export type ProjectImage = { src: string; alt: string; caption: string };
export type ProjectSpec = { label: string; value: string };
export type ProjectSection = {
  id: string;
  title: string;
  paragraphs?: string[];
  bullets?: string[];
  /** Formulas shown in a monospace block. */
  equations?: string[];
};
export type PipelineStep = { title: string; detail: string };

export type Project = {
  slug: string;
  title: string;
  category: ProjectCategory;
  tagline: string;
  org: string;
  role: string;
  period?: string;
  stack: string[];
  /** One or two sentences for the card. */
  summary: string;
  overview: string[];
  /** Key facts shown as a two-column table ("At a glance"). */
  specs?: ProjectSpec[];
  results: ProjectResult[];
  sections: ProjectSection[];
  pipelineTitle?: string;
  pipeline?: PipelineStep[];
  images: ProjectImage[];
  relatedAuv?: string;
  relatedPaper?: string;
  relatedProjects?: string[];
};

const img = (slug: string, name: string, alt: string, caption: string): ProjectImage => ({
  src: `projects/${slug}/${name}.webp`,
  alt,
  caption,
});

export function thumbOf(src: string) {
  return src.replace(/\.webp$/, "-thumb.webp");
}

export const CATEGORY_LABEL: Record<ProjectCategory, string> = {
  AUV: "AUV",
  Software: "Software",
  Research: "Research",
  Internship: "Internship",
};

